#!/bin/sh
# Mirror the HD cog and toon build sources from the working folder (../open-toontown-hd) into hd-build/ in this repo.
# Kept: build scripts, notes, final preview images, the toon Blender project.
# Left out: work/ scratch renders, baked textures and export dumps (all regenerated by the scripts), Blender backups,
# and the original game models and reference sheets.
set -e
SRC="${1:-$(cd "$(dirname "$0")/../.." && pwd)/open-toontown-hd}"
DST="$(cd "$(dirname "$0")/.." && pwd)/hd-build"
mkdir -p "$DST/cogs" "$DST/toons"
rsync -a --delete --prune-empty-dirs \
  --include='*/' --include='work/*.py' --exclude='work/**' \
  --include='*.py' --include='*.md' --include='preview*.png' --include='medallions_*.png' --exclude='*' \
  "$SRC/cog-turnarounds/_hd_build/" "$DST/cogs/"
rsync -a --delete --prune-empty-dirs \
  --include='*/' --include='work/*.py' --exclude='work/**' \
  --include='*.py' --include='*.md' --include='preview*.png' --include='*.blend' --exclude='*' \
  "$SRC/toon-hd-build/" "$DST/toons/"
